UPDATE learning_plan_unit_entry
SET phonetic = CASE id
    WHEN #{item.id} THEN #{item.phonetic}
    END,
    meaning_text = CASE id
    WHEN #{item.id} THEN #{item.meaningText}
    END,
    context_meaning = CASE id
    WHEN #{item.id} THEN #{item.contextMeaning}
    END,
    assessment_json = CASE id
    WHEN #{item.id} THEN #{item.assessmentJson}
    END,
    accepted_spellings_json = CASE id
    WHEN #{item.id} THEN #{item.acceptedSpellingsJson}
    END,
    update_time = #{list[0].updateTime},
    update_by = #{list[0].updateBy}
WHERE id IN
#{item.id}
